import type { SidebarsConfig } from "@docusaurus/plugin-content-docs";

import type { IconName } from "./src/components/Icon";

type SidebarItemConfig = Extract<SidebarsConfig[string], unknown[]>[number];

// Generated by docusaurus-plugin-typedoc on every build, from src/index.ts.
// eslint-disable-next-line @typescript-eslint/no-require-imports
const apiItems = require("./docs/api/typedoc-sidebar.cjs");

/**
 * A sidebar entry for a page, with the icon the sidebar's CSS draws before it.
 * @param id The page's doc id.
 * @param icon Its icon, a file of static/img/icons/.
 * @returns The entry.
 */
function page(id: string, icon: IconName): SidebarItemConfig {
    return { type: "doc", id, className: `sidebar-icon sidebar-icon--${icon}` };
}

/**
 * A titled group of pages, always open, as the section headings of the sidebar.
 * @param label Its heading.
 * @param items Its pages.
 * @returns The group.
 */
function group(label: string, items: SidebarItemConfig[]): SidebarItemConfig {
    return { type: "category", label, collapsible: false, className: "sidebar-group", items };
}

// One sidebar per section tab, as the tabs under the navbar switch between them.
const sidebars: SidebarsConfig = {
    start: [
        page("index", "home"),
        group("Get started", [
            page("get-started/installation", "package"),
            page("get-started/quickstart", "rocket"),
            page("get-started/runtimes", "devices"),
        ]),
    ],
    concepts: [
        group("Architecture", [page("concepts/hosted-lsp", "server"), page("concepts/networks", "globe")]),
        group("Keys and signing", [
            page("concepts/keys-and-recovery", "key"),
            page("concepts/no-blind-signing", "shield"),
            page("concepts/watchtower", "eye"),
        ]),
        group("Runtime", [page("concepts/poller-and-events", "refresh"), page("concepts/storage", "database")]),
    ],
    guides: [
        group("Setup", [page("guides/register-a-tenant", "user-plus")]),
        group("Channels", [page("guides/open-a-channel", "link"), page("guides/close-a-channel", "x-circle")]),
        group("Payments", [
            page("guides/receive-a-payment", "arrow-down"),
            page("guides/send-a-payment", "arrow-up"),
            page("guides/decode-an-invoice", "scan"),
        ]),
        group("In production", [
            page("guides/events-and-errors", "bell"),
            page("guides/react-native", "phone"),
            page("guides/backgrounding", "moon"),
        ]),
    ],
    reference: [
        group("Reference", [
            page("reference/options", "sliders"),
            page("reference/events", "bell"),
            page("reference/errors", "alert"),
            page("reference/constants", "hash"),
        ]),
    ],
    api: [{ type: "doc", id: "api/index", label: "Overview", className: "sidebar-icon sidebar-icon--list" }, ...apiItems],
    resources: [
        group("Project", [page("resources/status", "flag"), page("resources/compatibility", "layers"), page("resources/faq", "help")]),
        group("Deep dives", [page("resources/security", "lock"), page("resources/under-the-hood", "code")]),
    ],
};

export default sidebars;
